    {
      "id": "P1",
      "proposition": "Replacing § 49-10-1403(e), the bill requires a participating student's parent to ensure annual administration of all TCAP tests, or state-board-authorized successor tests, administered to public school students in the same grade or course subject, subject to the disability exemption in the replacement subsection.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "(A) Shall ensure that the participating student is annually"
    },
    {
      "id": "P2",
      "proposition": "Under replacement § 49-10-1403(e), a participating student's parent must ensure that, in grade eleven, the student takes the examination administered to public school eleventh graders pursuant to § 49-6-6001(b)(1), subject to the subsection's disability exemption.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "(B) In grade eleven (11) shall ensure that the student is"
    },
    {
      "id": "P3",
      "proposition": "Under replacement § 49-10-1403(e), a participating student's parent must ensure that, in kindergarten through grade three, the student is annually administered each of the three Tennessee universal reading screeners, or state-board-approved universal reading screeners described in § 49-1-905(c), during each of the three administration windows established by the department of education pursuant to § 49-1-905(c)(1), subject to the subsection's disability exemption.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "(C) In any of the grades kindergarten through three (K-3) shall"
    },
    {
      "id": "P4",
      "proposition": "Replacement § 49-10-1403(e) requires a participating student's results on tests administered under that subsection to be reported to the student's parent.",
      "importance": "supporting",
      "section": "SECTION 1",
      "source_quote": "this subsection (e) must be reported to the parent of the student."
    },
    {
      "id": "P5",
      "proposition": "Replacement § 49-10-1403(e) exempts students with disabilities who would have participated in alternate assessments, as determined on the student's IEP, from the requirements of that subsection.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "assessments, as determined on the student's IEP, are exempt from the"
    },
    {
      "id": "P6",
      "proposition": "Replacing § 49-6-2606(a)(1), the bill makes annual administration of TCAP tests, or state-board-authorized successor tests, administered to public school students in the same grade or course subject a condition of a student's participation in the program.",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "(1) As a condition of participating in the program:"
    },
    {
      "id": "P7",
      "proposition": "Under replacement § 49-6-2606(a)(1), participating students in grade eleven must be administered the examination administered to public school eleventh graders pursuant to § 49-6-6001(b)(1), as a condition of program participation.",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "(B) Participating students in grade eleven (11) must be administered the"
    },
    {
      "id": "P8",
      "proposition": "Under replacement § 49-6-2606(a)(1), participating students in kindergarten through grade three must annually be administered each of the three Tennessee universal reading screeners, or state-board-approved universal reading screeners described in § 49-1-905(c), during each of the three administration windows established by the department of education pursuant to § 49-1-905(c)(1), as a condition of program participation.",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "(C) Participating students in kindergarten through grade three (K-3) must"
    },
    {
      "id": "P9",
      "proposition": "The act takes effect July 1, 2025.",
      "importance": "supporting",
      "section": "SECTION 3",
      "source_quote": "This act takes effect July 1, 2025, the public welfare requiring it."
    }
  ]
}
